-- DROP TABLES

DROP TABLE IF EXISTS donations CASCADE;

DROP TABLE IF EXISTS milestones CASCADE;

DROP TABLE IF EXISTS surveys CASCADE;

DROP TABLE IF EXISTS registrations CASCADE;

DROP TABLE IF EXISTS event_occurrences CASCADE;

DROP TABLE IF EXISTS event_templates CASCADE;

DROP TABLE IF EXISTS participants CASCADE;


-- CREATE TABLES

CREATE TABLE participants (
  participant_id INTEGER GENERATED ALWAYS AS IDENTITY,
  participant_email TEXT,
  participant_first_name TEXT,
  participant_last_name TEXT,
  participant_dob TEXT,
  participant_role TEXT,
  participant_phone TEXT,
  participant_city TEXT,
  participant_state TEXT,
  participant_zip TEXT,
  participant_school_or_employer TEXT,
  participant_field_of_interest TEXT,
  password TEXT NOT NULL,
  PRIMARY KEY (participant_id)
);

CREATE TABLE event_templates (
  event_template_id INTEGER GENERATED ALWAYS AS IDENTITY,
  event_name TEXT,
  event_type TEXT,
  event_description TEXT,
  event_recurrence_pattern TEXT,
  event_default_capacity TEXT,
  PRIMARY KEY (event_template_id)
);

CREATE TABLE event_occurrences (
  event_occurrence_id INTEGER GENERATED ALWAYS AS IDENTITY,
  event_date_time_start TIMESTAMPTZ,
  event_date_time_end TIMESTAMPTZ,
  event_location TEXT,
  event_capacity TEXT,
  event_registration_deadline TEXT,
  event_template_id INTEGER REFERENCES event_templates(event_template_id) ON DELETE CASCADE,
  PRIMARY KEY (event_occurrence_id)
);

CREATE TABLE registrations (
  registration_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  registration_status TEXT,
  registration_attended_flag BOOLEAN,
  registration_check_in_time TEXT,
  registration_created_at TEXT,
  participant_id INTEGER REFERENCES participants(participant_id) ON DELETE CASCADE,
  event_occurrence_id INTEGER REFERENCES event_occurrences(event_occurrence_id) ON DELETE CASCADE
);

CREATE TABLE surveys (
  survey_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  survey_satisfaction_score INTEGER,
  survey_usefulness_score INTEGER,
  survey_instructor_score INTEGER,
  survey_recommendation_score INTEGER,
  survey_overall_score INTEGER,
  survey_nps_bucket TEXT,
  survey_comments TEXT,
  survey_submission_date DATE,
  participant_id INTEGER REFERENCES participants(participant_id) ON DELETE CASCADE,
  event_occurrence_id INTEGER REFERENCES event_occurrences(event_occurrence_id) ON DELETE CASCADE
);

CREATE TABLE milestones (
  milestone_id INTEGER GENERATED ALWAYS AS IDENTITY,
  milestone_title TEXT,
  milestone_date DATE,
  participant_id INTEGER REFERENCES participants(participant_id) ON DELETE CASCADE,
  PRIMARY KEY (milestone_id)
);

CREATE TABLE donations (
  donation_id INTEGER GENERATED ALWAYS AS IDENTITY,
  donation_date DATE,
  donation_amount NUMERIC(10,2),
  participant_id INTEGER REFERENCES participants(participant_id) ON DELETE CASCADE,
  PRIMARY KEY (donation_id)
);


