-- RESEED IDENTITY SEQUENCES

SELECT setval(pg_get_serial_sequence('participants','participant_id'), (SELECT COALESCE(MAX(participant_id),0)+1 FROM participants), false);

SELECT setval(pg_get_serial_sequence('event_templates','event_template_id'), (SELECT COALESCE(MAX(event_template_id),0)+1 FROM event_templates), false);

SELECT setval(pg_get_serial_sequence('event_occurrences','event_occurrence_id'), (SELECT COALESCE(MAX(event_occurrence_id),0)+1 FROM event_occurrences), false);

SELECT setval(pg_get_serial_sequence('registrations','registration_id'), (SELECT COALESCE(MAX(registration_id),0)+1 FROM registrations), false);

SELECT setval(pg_get_serial_sequence('surveys','survey_id'), (SELECT COALESCE(MAX(survey_id),0)+1 FROM surveys), false);

SELECT setval(pg_get_serial_sequence('milestones','milestone_id'), (SELECT COALESCE(MAX(milestone_id),0)+1 FROM milestones), false);

SELECT setval(pg_get_serial_sequence('donations','donation_id'), (SELECT COALESCE(MAX(donation_id),0)+1 FROM donations), false);
